(()=>{
 const form=document.querySelector('#newsletter-form');if(!form)return;
 let startedAt=Date.now(),busy=false,enabled=false;const button=form.querySelector('button[type="submit"]'),status=form.querySelector('[role="status"]');
 fetch('/api/newsletter',{headers:{Accept:'application/json'},cache:'no-store',signal:AbortSignal.timeout(10000)}).then(r=>r.ok?r.json():null).then(data=>{enabled=data?.enabled===true;button.disabled=!enabled;status.textContent=enabled?'Vous recevrez un e-mail pour confirmer votre inscription.':'Pour être informé des parutions, contactez les auteurs.';if(!enabled){form.querySelector('.newsletter-fields').hidden=true;button.hidden=true;}}).catch(()=>{status.textContent='Pour être informé des parutions, contactez les auteurs.';form.querySelector('.newsletter-fields').hidden=true;button.hidden=true;});
 form.addEventListener('submit',async event=>{event.preventDefault();if(!enabled||busy||!form.reportValidity())return;busy=true;button.disabled=true;const values=new FormData(form);try{const r=await fetch('/api/newsletter',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:values.get('email'),consent:values.get('consent')==='on',website:values.get('website'),startedAt}),signal:AbortSignal.timeout(15000)});const data=await r.json();if(!r.ok||data.ok!==true)throw Error(data.error||'L’inscription n’a pas pu être confirmée.');status.textContent=data.message;form.reset();startedAt=Date.now();}catch(error){status.textContent=error.message||'Réessayez plus tard.';}finally{busy=false;button.disabled=false;}});
})();
